// Diccionario de i18n de la APP INTERNA (/app/**, /q/[token], correos
// transaccionales). Idioma resuelto por Accept-Language del navegador (ver
// middleware.ts + src/lib/context.ts → currentLocale()), sin toggle manual.
//
// Distinto de src/i18n/ui.ts (ese es SOLO para la landing pública, que usa
// rutas /en/* explícitas). Aquí no hay rutas duplicadas: la MISMA ruta
// /app/cotizaciones sirve en es o en según el navegador de quien la visita.
//
// Uso en un .astro:
//   import { t } from '../../i18n/app';
//   import { currentLocale } from '../../lib/context';
//   const L = currentLocale();
//   ... {t(L, 'sidebar.grupo.principal')} ...
//
// ⚠️ Este diccionario se llena de forma INCREMENTAL — ver docs/historial-app-features.md
// para el registro de qué páginas ya están cubiertas. Una key ausente cae al
// español (fail-safe) vía el fallback de t().

export type AppLocale = "es" | "en";

