export type AppStringKey = keyof (typeof appStrings)["es"];

/** Traduce `key` al locale dado; si falta en `en`, cae a `es` (nunca revienta). */
export function t(locale: AppLocale, key: AppStringKey): string {
    return appStrings[locale]?.[key] ?? appStrings.es[key] ?? key;
}

// ── Runtime de AppLayout para el <script> cliente ──────────────────────────
// El script grande de AppLayout.astro (Cmd+K, drawer de Ayuda, notificaciones,
// toasts) NO es `is:inline` y por lo tanto no puede leer `t()` directamente en
// tiempo de ejecución. En vez de eso, este objeto se serializa UNA vez server-
// side (vía `<script is:inline define:vars>`) a `window.CORD_I18N` y el script
// grande lee de ahí. Mantiene el mismo patrón "todo ya resuelto en el idioma
// correcto" — el cliente nunca decide idioma, solo consume strings.
