        chatFallbackReply: "Buena pregunta. En este entorno de demostración Cord AI todavía no puede responder dudas específicas fuera de las preguntas frecuentes — pero es solo para resolver consultas, nunca ejecuta acciones dentro de tu cuenta. Si no encuentras tu respuesta arriba, escríbenos desde el Centro de ayuda.",
